def card(p):
    """Format a vocabulary profile as a plain-text card for terminal display."""
    lines = []

    if "length" in p:
        lines.append(f"Words: {p['length']}")

    if "variety" in p:
        variety = p["variety"]
        if isinstance(variety, float):
            lines.append(f"Variety: {variety:.1f}%")
        else:
            lines.append(f"Variety: {variety}")

    if "top_words" in p and p["top_words"]:
        top = p["top_words"]
        words_str = ", ".join(f"{word} ({count})" for word, count in top)
        lines.append(f"Top words: {words_str}")

    return "\n".join(lines)
